function result=run_constraint_generation_repair(model,w0,D,cst,referenceDose,settings)
% Active-gate outer loop. Exact unchanged clinical evaluator is authoritative.
if nargin<6,settings=struct();end;settings=defaults(settings);D=sparse(double(D));w=reshape(double(w0),[],1);spec=build_clinical_gate_spec(D,cst,referenceDose,2,0.2);active=initialize_rows(D,w,spec,settings);history=repmat(empty_history(),0,1);total=tic;aggregate=struct('objective',0,'gradient',0,'constraints',0,'jacobian',0);last=[];
for outer=1:settings.maxOuter
 [A,cl,cu,rowMeta]=assemble(active);ip=struct('ipopt',struct('max_iter',settings.maxIter,'max_cpu_time',settings.maxCPU,'print_level',3,'acceptable_iter',8,'acceptable_obj_change_tol',1e-5));last=solve_static_gate_ipopt(model,w,A,cl,cu,ip);w=last.w;values=evaluate_clinical_gates(D,w,spec,false);pass=gate_pass(values,spec,settings.gateTolerance);newRows=discover_rows(D,w,spec,values,active,settings);for f=fieldnames(aggregate)',k=f{1};aggregate.(k)=aggregate.(k)+last.callbackCounts.(k);end
 history(end+1)=struct('outer',outer,'activeRows',size(A,1),'newRows',numel(newRows),'exactGatePass',pass,'objective',last.objective,'iterations',last.iterations,'primalInfeasibility',last.primalInfeasibility,'dualInfeasibility',last.dualInfeasibility,'solverWallSeconds',last.wallSeconds,'exactGateEvaluations',1); %#ok<AGROW>
 if pass,stopReason='EXACT_GATES_PASS';break;end;if isempty(newRows),stopReason='NO_NEW_ACTIVE_ROWS';break;end;if ~last.solverUsable,stopReason='NUMERICAL_FAILURE';break;end;active=[active;newRows]; %#ok<AGROW>
 if outer==settings.maxOuter,stopReason='OUTER_BUDGET_EXCEEDED';end
end
values=evaluate_clinical_gates(D,w,spec,false);rows=gate_table(values,spec,settings.gateTolerance);result=struct('w',w,'lastSolver',last,'history',history,'activeRows',{active},'rowMeta',{rowMeta},'exactGateValues',values,'exactGateRows',rows,'exactGatePass',all([rows.pass]),'stopReason',stopReason,'outerIterations',numel(history),'exactGateEvaluations',numel(history),'callbackCounts',aggregate,'wallSeconds',toc(total));
end
function s=defaults(s),d=struct('initialDmaxRows',4,'initialTargetRows',2,'violationBatch',32,'maxOuter',4,'maxIter',80,'maxCPU',120000,'gateTolerance',1e-7);f=fieldnames(d);for i=1:numel(f),if ~isfield(s,f{i}),s.(f{i})=d.(f{i});end,end,end
function a=initialize_rows(D,w,spec,s),dose=D*w;a=repmat(empty_row(),0,1);for i=1:numel(spec),sp=spec(i);x=dose(sp.vox);if strcmp(sp.metric,'Dmean'),a(end+1)=make_row(mean(D(sp.vox,:),1),-Inf,sp.limit,i,0,'Dmean_exact');elseif strcmp(sp.metric,'Dmax'),[~,o]=sort(x,'descend');for q=reshape(o(1:min(s.initialDmaxRows,numel(o))),1,[]),a(end+1)=make_row(D(sp.vox(q),:),-Inf,sp.limit,i,sp.vox(q),'Dmax_active');end;else,[~,o]=sort(x,'ascend');allowed=floor(sp.percentile/100*numel(o));q0=max(1,allowed+1);q1=min(numel(o),q0+s.initialTargetRows-1);for q=q0:q1,a(end+1)=make_row(D(sp.vox(o(q)),:),sp.limit,Inf,i,sp.vox(o(q)),[sp.metric '_active']);end;end,end;a=deduplicate(a);end
function rows=discover_rows(D,w,spec,values,active,s),dose=D*w;rows=repmat(empty_row(),0,1);for i=1:numel(spec),sp=spec(i);if strcmp(sp.sense,'upper')&&values(i)<=sp.limit+s.gateTolerance,continue;elseif strcmp(sp.sense,'lower')&&values(i)>=sp.limit-s.gateTolerance,continue;end;x=dose(sp.vox);if strcmp(sp.metric,'Dmax'),cand=find(x>sp.limit+s.gateTolerance);[~,o]=sort(x(cand),'descend');cand=cand(o(1:min(s.violationBatch,numel(o))));for q=reshape(cand,1,[]),rows(end+1)=make_row(D(sp.vox(q),:),-Inf,sp.limit,i,sp.vox(q),'Dmax_violation');end;elseif strcmp(sp.metric,'Dmean'),rows(end+1)=make_row(mean(D(sp.vox,:),1),-Inf,sp.limit,i,0,'Dmean_exact');else,[~,o]=sort(x,'ascend');allowed=floor(sp.percentile/100*numel(o));bad=find(x(o)<sp.limit-s.gateTolerance);bad=bad(bad>allowed);bad=bad(1:min(s.violationBatch,numel(bad)));for q=reshape(bad,1,[]),v=sp.vox(o(q));rows(end+1)=make_row(D(v,:),sp.limit,Inf,i,v,[sp.metric '_violation']);end;end,end;rows=deduplicate_against(rows,active);end
function [A,cl,cu,m]=assemble(a),if isempty(a),A=sparse(0,0);cl=[];cu=[];m={};return;end;A=vertcat(a.row);cl=[a.lower]';cu=[a.upper]';m={a.kind}';end
function r=empty_row(),r=struct('row',sparse(1,0),'lower',-Inf,'upper',Inf,'specIndex',0,'voxel',0,'kind','');end
function r=make_row(v,l,u,i,x,k),r=struct('row',sparse(v),'lower',l,'upper',u,'specIndex',i,'voxel',x,'kind',k);end
function a=deduplicate(a),if isempty(a),return;end;key=arrayfun(@(x)sprintf('%d:%d:%g:%g',x.specIndex,x.voxel,x.lower,x.upper),a,'UniformOutput',false);[~,ix]=unique(key,'stable');a=a(ix);end
function r=deduplicate_against(r,a),if isempty(r),return;end;old=arrayfun(@(x)sprintf('%d:%d:%g:%g',x.specIndex,x.voxel,x.lower,x.upper),a,'UniformOutput',false);new=arrayfun(@(x)sprintf('%d:%d:%g:%g',x.specIndex,x.voxel,x.lower,x.upper),r,'UniformOutput',false);r=r(~ismember(new,old));r=deduplicate(r);end
function y=gate_pass(v,s,t),y=true;for i=1:numel(s),if strcmp(s(i).sense,'lower'),y=y&&v(i)>=s(i).limit-t;else,y=y&&v(i)<=s(i).limit+t;end,end,end
function r=gate_table(v,s,t),r=repmat(struct('structure','','metric','','value',0,'limit',0,'sense','','pass',false),numel(s),1);for i=1:numel(s),if strcmp(s(i).sense,'lower'),p=v(i)>=s(i).limit-t;else,p=v(i)<=s(i).limit+t;end;r(i)=struct('structure',s(i).structure,'metric',s(i).metric,'value',v(i),'limit',s(i).limit,'sense',s(i).sense,'pass',p);end,end
function r=empty_history(),r=struct('outer',0,'activeRows',0,'newRows',0,'exactGatePass',false,'objective',0,'iterations',0,'primalInfeasibility',0,'dualInfeasibility',0,'solverWallSeconds',0,'exactGateEvaluations',0);end
